-- ============================================================================
-- gasvalue: Flare Gas to Value & LPG/CNG joins the catalogue, the FIRST course
-- of the Energy Transition module.
--
-- Catalogue row (module 'energy_transition', the academy module the lead ruled
-- for the two Energy Transition courses; path_order 51, directly above the three
-- Commercial & Trading and Supply Chain courses live since 2026-09-19, crude at
-- 48, refinery at 49 and supply at 50, and directly below its wave sibling
-- carbon at 52; prereq_slug NULL, the carried-over answer "no hard prerequisite
-- inside a module"; school left at its default, as every Facilities, Economics,
-- Assurance and Commercial & Trading course leaves it, so the fees are the
-- published school-level rows) plus the three capstones and their eighteen
-- graded fields, generated by tools/course-waves/gasvalue/gen_course.py from
-- fields.json, precision.json and capstone.json, which gasvalue_capstone.mjs
-- writes from the capstone records in gasvalue_fields_capstone.mjs through the
-- vendored engines. The three tier structures (78 lesson keys) and the 396
-- questions are the three deep seeds; the go-live is a fifth migration and is
-- HELD until a NextGen production upload carries the route
-- /dashboard/apps/gasvalue AND the Suite production upload carrying Suite main
-- 06aef5d63 (Suite #543 MD5-0, #545 MD4-0, #546 MD45-1: the Flare Gas to Value
-- and LPG & CNG Rollout page repairs this course teaches) is live. This file
-- does not depend on carbon: either may be seeded first.
--
-- THE ONE SENTENCE THE COURSE IS. A flare is a measured gas before it is an
-- emission or a product: its heating value, its liquids and its carbon come
-- from the analysis by the mole, the flare's CO2 and methane follow the rule's
-- two efficiencies, a route is credited only for the share it recovers against
-- a declared counterfactual, and the LPG vessel, the vaporizer, the carousel,
-- the CNG bank and the cascade are each sized on the basis the engine states.
--
-- THE ENGINES. engines/downstream/flareToValue.js and lpgCng.js (with
-- scaleCapex and SCALING_EXPONENT from modularRefinery.js), vendored
-- sha-identical with engines df31f53 (MD45-1, after MD4-0 and MD5-0); the recon
-- findings on the graded paths were repaired upstream in MD4-0 and MD45-1.
--
-- EVERY GRADED FIELD IS A NUMBER THE ENGINE RETURNS, at full precision, graded
-- at ONE UNIT IN THE LAST PLACE THE PROMPT ASKS FOR: the heating value, the
-- liquids, the C3+ mass, the CNG a year, the margin per Mscf, the breakeven
-- credit price, the usable LPG, the vaporizer duty, the carousel wait, the bank
-- mass and the payback to four decimals at 0.0001; the capital cost to two at
-- 0.01 dollars; the gas left in the cascade to three at 0.001 kg. THE ONE
-- EXCEPTION: tonnes a year of a flare or an abatement are asked to three
-- decimals and graded at 0.01 t, ten units, because the engine's LB_PER_KG is
-- the exact pound's reciprocal to nine figures only and on a flare of 300,000
-- t a year the oracle and the engine part by up to about 1.1e-3 t. The grader
-- (academy_submit_capstone) casts expected, tol and answer to numeric and
-- accepts |answer - expected| <= tol. No verdict, basis word, richness band,
-- refusal or count is graded. No field reads a date or a clock.
--
-- THE PROMPTS are capstone.json's, verbatim: every condition a field needs and
-- the precision it is graded at, and nothing that hands over an answer. No
-- graded value of any tier is printed in any prompt as its own rounding or
-- within its tolerance, none of the engine-derived intermediates (the
-- normalised fractions, the carbon per mole, the scf a year, the margin, the
-- blend's density and latent heat, the arrival rate, the absolute pressures,
-- Z, the kg per fill, the derived CNG consumption) is printed as its own
-- rounding, and neither derived count (the positions wholly working, the fills
-- before recharge) is printed as a whole number. No graded value is within its
-- tolerance of any number the teaching digest prints, and no two graded values
-- are within the looser of their tolerances.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('gasvalue', 'Flare Gas to Value & LPG/CNG', 'energy_transition', 51, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'gasvalue', 'beginner', 'associate',
  'ERIEMU, a flow station of an invented operator flaring its associated gas: the laboratory sheet and the flare study',
  'The gas by the mole and the flare by the rule',
  'ERIEMU FLOW STATION. The station flares its associated gas. Every figure is invented and illustrative. The laboratory sheet, as mole fractions with the component figures to use: Methane (C1) 0.7215: 1 carbon per molecule, molar mass 16.043 lb/lbmol, heating value 1010 Btu/scf; Ethane (C2) 0.0968: 2 carbon per molecule, molar mass 30.07 lb/lbmol, heating value 1770 Btu/scf, liquid density 2.971 lb/gal; Propane (C3) 0.0634: 3 carbon per molecule, molar mass 44.096 lb/lbmol, heating value 2516 Btu/scf, liquid density 4.233 lb/gal; Iso-butane (IC4) 0.0142: 4 carbon per molecule, molar mass 58.122 lb/lbmol, heating value 3252 Btu/scf, liquid density 4.695 lb/gal; n-Butane (NC4) 0.0236: 4 carbon per molecule, molar mass 58.122 lb/lbmol, heating value 3263 Btu/scf, liquid density 4.872 lb/gal; Pentanes plus (C5) 0.0127: 5 carbon per molecule, molar mass 72.15 lb/lbmol, heating value 4010 Btu/scf, liquid density 5.253 lb/gal; Nitrogen (N2) 0.0231: 0 carbon per molecule, molar mass 28.014 lb/lbmol, heating value 0 Btu/scf; Carbon dioxide (CO2) 0.0367: 1 carbon per molecule, molar mass 44.01 lb/lbmol, heating value 0 Btu/scf. The sheet is used as reported: scale it to one before using it. Take one lb-mol as 379.49 scf and one kg as 2.20462262 lb. The station flares 12.4 MMscfd on 347 days a year. The flare study gives a destruction efficiency of 0.976 and a combustion efficiency of 0.961, and uses a methane global warming potential of 28.7. Work the flare by 40 CFR 98.233(n) with CO2 at 44.009 and methane at 16.043 kg/kmol. Give six numbers. (1) The gas''s gross heating value in Btu/scf. (2) Its liquids content, propane and heavier, in gallons per Mscf. (3) The mass of propane and heavier in one Mscf, in kg. (4) The flare''s CO2 in tonnes a year. (5) Its methane in tonnes a year. (6) Its CO2e in tonnes a year. Quote (1) to (3) to 4 decimals and (4) to (6) to 3.',
  jsonb_build_array(
    jsonb_build_object('key','eriemu_ghv_btu_scf', 'label','Gross heating value of the gas', 'unit','Btu/scf', 'expected',1243.6266, 'tol',0.0001),
    jsonb_build_object('key','eriemu_gpm_c3plus', 'label','Liquids content, propane and heavier', 'unit','gal/Mscf', 'expected',3.432605, 'tol',0.0001),
    jsonb_build_object('key','eriemu_c3plus_kg_per_mscf', 'label','Mass of propane and heavier in one Mscf', 'unit','kg/Mscf', 'expected',7.11980244, 'tol',0.0001),
    jsonb_build_object('key','eriemu_flare_co2_t', 'label','Flare CO2 a year', 'unit','tonnes a year', 'expected',297803.716, 'tol',0.01),
    jsonb_build_object('key','eriemu_flare_ch4_t', 'label','Flare methane a year', 'unit','tonnes a year', 'expected',1440.251, 'tol',0.01),
    jsonb_build_object('key','eriemu_flare_co2e_t', 'label','Flare CO2e a year', 'unit','tonnes a year', 'expected',339138.908, 'tol',0.01)
  )
),
(
  'gasvalue', 'intermediate', 'professional',
  'ADIBAWA, an invented flared parcel bid as CNG: the plant, its year, the counterfactual and the credit test',
  'The route, the recovered share and the credit',
  'ADIBAWA GAS PARCEL. A developer bids to take a flared parcel as CNG. Every figure is invented and illustrative. The gas, as mole fractions with the component figures to use: Methane (C1) 0.801: 1 carbon per molecule, molar mass 16.043 lb/lbmol, heating value 1010 Btu/scf; Ethane (C2) 0.071: 2 carbon per molecule, molar mass 30.07 lb/lbmol, heating value 1770 Btu/scf, liquid density 2.971 lb/gal; Propane (C3) 0.041: 3 carbon per molecule, molar mass 44.096 lb/lbmol, heating value 2516 Btu/scf, liquid density 4.233 lb/gal; Iso-butane (IC4) 0.009: 4 carbon per molecule, molar mass 58.122 lb/lbmol, heating value 3252 Btu/scf, liquid density 4.695 lb/gal; n-Butane (NC4) 0.015: 4 carbon per molecule, molar mass 58.122 lb/lbmol, heating value 3263 Btu/scf, liquid density 4.872 lb/gal; Pentanes plus (C5) 0.008: 5 carbon per molecule, molar mass 72.15 lb/lbmol, heating value 4010 Btu/scf, liquid density 5.253 lb/gal; Nitrogen (N2) 0.027: 0 carbon per molecule, molar mass 28.014 lb/lbmol, heating value 0 Btu/scf; Carbon dioxide (CO2) 0.028: 1 carbon per molecule, molar mass 44.01 lb/lbmol, heating value 0 Btu/scf. Take one lb-mol as 379.49 scf and one kg as 2.20462262 lb. The parcel is 16.8 MMscfd on 342 days a year. The flare today has a destruction efficiency of 0.968 and a combustion efficiency of 0.952; use a methane global warming potential of 27.9, CO2 at 44.009 and methane at 16.043 kg/kmol, and 40 CFR 98.233(n). The CNG plant yields 17.2 kg of CNG per Mscf processed and recovers 0.87 of the parcel; CNG sells at 0.43 dollars per kg. A reference plant of 7 MMscfd cost 27000000 dollars; scale it by the modular power law with an exponent of 0.9. Fixed operating cost is 2100000 dollars a year and variable operating cost 0.38 dollars per Mscf of the parcel. The declared counterfactual: cng displacing diesel in port harcourt haulage; burning the CNG emits 236000 tCO2e a year and the diesel it displaces would have emitted 281000 tCO2e a year. The bid team typed credit prices of 30, 10, 20, 15 dollars per tonne, in that order, against a hurdle margin of 39500000 dollars a year. Give six numbers. (1) The plant''s capital cost in dollars, to 2 decimals. (2) The CNG it makes in kg a year, to 4 decimals. (3) Its gross margin per Mscf of the parcel in dollars, to 4 decimals. (4) The flare CO2e the plant avoids in tonnes a year, to 3 decimals. (5) The net abatement against the counterfactual in tonnes a year, to 3 decimals. (6) The credit price at which the route just clears the hurdle, in dollars per tonne, to 4 decimals.',
  jsonb_build_array(
    jsonb_build_object('key','adibawa_capital_usd', 'label','Capital cost of the CNG plant', 'unit','USD', 'expected',59368200.01, 'tol',0.01),
    jsonb_build_object('key','adibawa_cng_kg_per_year', 'label','CNG made a year', 'unit','kg a year', 'expected',85977158.4, 'tol',0.0001),
    jsonb_build_object('key','adibawa_value_per_mscf', 'label','Gross margin per Mscf of the parcel', 'unit','USD per Mscf', 'expected',5.689023, 'tol',0.0001),
    jsonb_build_object('key','adibawa_avoided_co2e_t', 'label','Flare CO2e the plant avoids', 'unit','tonnes a year', 'expected',376796.694, 'tol',0.01),
    jsonb_build_object('key','adibawa_net_abatement_t', 'label','Net abatement against the declared counterfactual', 'unit','tonnes a year', 'expected',421796.694, 'tol',0.01),
    jsonb_build_object('key','adibawa_breakeven_credit_usd_per_t', 'label','Credit price at which the route just clears the hurdle', 'unit','USD per tonne', 'expected',16.152687, 'tol',0.0001)
  )
),
(
  'gasvalue', 'advanced', 'expert',
  'ASABA, an invented energy hub where an LPG depot and a CNG station share a site',
  'The vessel, the carousel, the cascade and the taxi',
  'ASABA ENERGY HUB. An LPG depot and a CNG station share a site. Every figure is invented and illustrative. The LPG is propane 0.32 by liquid volume (density 506 kg/m3, molar mass 44.096 kg/kmol, latent heat 428 kJ/kg) and butane 0.68 by liquid volume (density 581 kg/m3, molar mass 58.122 kg/kmol, latent heat 383 kJ/kg). The vessel holds 220 m3 of water capacity and its code limit is a filling density of 0.43 of the water capacity by weight, with water at 15 C taken as 999.1 kg/m3. The vaporizer takes 780 kg/h of that LPG entering at 21 C (liquid heat capacity 2.5 kJ/kg K); at the vaporizer''s pressure it boils at 41 C, and the vapour leaves at 58 C (vapour heat capacity 1.7 kJ/kg K); add a design margin of 12 percent. The bottling carousel fills 4100 cylinders a day over a 11 hour shift, 2.3 minutes a cylinder, on 20 positions each available 0.93 of the time; run the queue on the positions wholly working. The CNG is gas of specific gravity 0.63 at 34 C, and every pressure below is read on a gauge; the site''s atmosphere is 1.013 bar. A storage bank of 3 m3 reads 245 bar. The cascade: Low bank 2.5 m3 at 180 bar, Mid bank 2.5 m3 at 225 bar, High bank 2.5 m3 at 260 bar; each taxi tank is 0.075 m3 and arrives at 15 bar and is filled to 200 bar, isothermally, equalising with the lowest bank first; use real-gas Z by Dranchuk-Abou-Kassem on Sutton pseudo-criticals. A taxi covers 62000 km a year on 11 litres of PMS per 100 km at 820 naira a litre (32.2 MJ a litre); CNG costs 410 naira a kg (47.1 MJ a kg), no measured consumption on CNG exists, and the converted engine turns CNG energy into distance 0.9 times as well as PMS energy. The conversion costs 1350000 naira and adds 72000 naira a year of maintenance. Give six numbers. (1) The usable LPG in the vessel, in tonnes, to 4 decimals. (2) The vaporizer''s design duty in kW, to 4 decimals. (3) The average wait of a cylinder for a position, in minutes, to 4 decimals. (4) The gas in the storage bank, in kg, to 4 decimals. (5) The gas left in the three cascade banks when the next taxi can no longer be filled to target, in kg, to 3 decimals. (6) The taxi''s simple payback in years, undiscounted, to 4 decimals.',
  jsonb_build_array(
    jsonb_build_object('key','asaba_usable_lpg_t', 'label','Usable LPG in the vessel', 'unit','tonnes', 'expected',94.5149, 'tol',0.0001),
    jsonb_build_object('key','asaba_vaporizer_design_kw', 'label','Design duty of the vaporizer', 'unit','kW', 'expected',115.262179, 'tol',0.0001),
    jsonb_build_object('key','asaba_carousel_wait_min', 'label','Average wait of a cylinder for a position', 'unit','minutes', 'expected',0.1642631615249336, 'tol',0.0001),
    jsonb_build_object('key','asaba_bank_mass_kg', 'label','Gas in the storage bank', 'unit','kg', 'expected',630.12764, 'tol',0.0001),
    jsonb_build_object('key','asaba_left_in_banks_kg', 'label','Gas left in the cascade when the next taxi cannot be filled', 'unit','kg', 'expected',845.298, 'tol',0.001),
    jsonb_build_object('key','asaba_payback_years', 'label','Simple payback of the taxi conversion, undiscounted', 'unit','years', 'expected',0.397483, 'tol',0.0001)
  )
)
on conflict (app_slug, tier) do nothing;
